Add-Rule @{ Name = 'FWShift-Guests_stay_out-1'; DisplayName = 'Guests stay out (1)'; Description = 'FWShift: Guests stay out'; Direction = 'Inbound'; Action = 'Block'; Enabled = 'True'; Profile = 'Any'; LocalAddress = @('10.0.0.0/8'); RemoteAddress = @('10.10.200.0/24') }
